INSERT INTO bare_acts (id, title, short_title, is_active)
INSERT INTO bare_act_sections (section_number, section_title, section_text, chapter_number, chapter_title, sequence_order, act_id)
VALUES 
('SMA-1', 'Short title, extent and commencement', 'This Act may be called the Special Marriage Act, 1954. It extends to the whole of India and applies to all citizens of India, whether residing in the territories to whom this Act extends or not.', 'CH1_PRELIMINARY', 'Preliminary', 1, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-4', 'Conditions relating to solemnization of special marriages', 'Conditions for a valid marriage:\n(a) Neither party has a spouse living.\n(b) Neither party is incapable of giving valid consent due to unsoundness of mind.\n(c) Male must be 21 years old; female must be 18 years old.\n(d) Parties are not within degrees of prohibited relationship.\n(e) In case of citizens abroad, parties to be domiciled in India.', 'CH1_PRELIMINARY', 'Preliminary', 2, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-5', 'Notice of intended marriage', 'When a marriage is intended to be solemnized under this Act, the parties to the marriage shall give notice thereof in writing in the form specified in the Second Schedule to the Marriage Officer of the district in which at least one of the parties to the marriage has resided for a period of not less than thirty days immediately preceding the date on which such notice is given.', 'CH2_SOLEMNIZATION', 'Solemnization of Special Marriages', 3, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-6', 'Marriage Notice Book and publication', 'The Marriage Officer shall keep all notices and shall enter a true copy of every such notice into the Marriage Notice Book. This book shall be open for inspection at all reasonable times. A copy of the notice shall be published in the Marriage Officer''s office.', 'CH2_SOLEMNIZATION', 'Solemnization of Special Marriages', 4, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-7', 'Objection to marriage', 'Any person may, before the expiration of thirty days from the date on which the notice has been published, object to the marriage on the ground that it would contravene one or more of the conditions specified in section 4.', 'CH2_SOLEMNIZATION', 'Solemnization of Special Marriages', 5, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-12', 'Place and form of solemnization', 'The marriage may be solemnized at the office of the Marriage Officer or at such other place within a reasonable distance therefrom as the parties may desire. The marriage may be solemnized in any form which the parties may choose to adopt. However, it shall not be complete and binding unless each party says to the other in the presence of the Marriage Officer and the three witnesses and in any language understood by the parties — ''I, (A), take thee (B), to be my lawful wife (or husband)''.', 'CH2_SOLEMNIZATION', 'Solemnization of Special Marriages', 6, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-13', 'Certificate of marriage', 'After the solemnization of the marriage, the Marriage Officer shall enter a certificate thereof in the form specified in the Fourth Schedule in a book to be kept by him for that purpose and to be called the Marriage Certificate Book and such certificate shall be signed by the parties to the marriage and the three witnesses. The certificate shall be deemed to be conclusive evidence of the fact that a marriage under this Act has been solemnized and that all formalities respecting the signatures of witnesses have been complied with.', 'CH2_SOLEMNIZATION', 'Solemnization of Special Marriages', 7, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-15', 'Registration of marriages celebrated in other forms', 'Any marriage celebrated in any other form (religious or customary) may be registered under this Chapter if:\n(a) the parties have been living together as husband and wife.\n(b) neither party has more than one spouse living.\n(c) neither party is of unsound mind.\n(d) parties attained ages specified in Section 4.\n(e) parties are not within degrees of prohibited relationship.', 'CH3_REGISTRATION', 'Registration of Marriages celebrated in other forms', 8, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-19', 'Effect of marriage on joint family', 'The marriage solemnized under this Act of any member of an undivided family who professes the Hindu, Buddhist, Sikh or Jaina religion shall be deemed to effect his severance from such family.\n\nNote: This section is controversial and unique to SMA. It triggers an automatic partition from the Joint Hindu Family.', 'CH4_CONSEQUENCES', 'Consequences of Marriage under this Act', 9, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-21', 'Succession to property of parties married under Act', 'Notwithstanding any restrictions contained in any other law, succession to the property of any person whose marriage is solemnized under this Act, and to the property of the issue of such marriage, shall be regulated by the provisions of the Indian Succession Act, 1925, and not by the personal law of the parties.', 'CH4_CONSEQUENCES', 'Consequences of Marriage under this Act', 10, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-22', 'Restitution of conjugal rights', 'When either the husband or the wife has, without reasonable excuse, withdrawn from the society of the other, the aggrieved party may apply for restitution of conjugal rights to the district court.', 'CH5_RESTITUTION_AND_SEPARATION', 'Restitution of Conjugal Rights and Judicial Separation', 11, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-23', 'Judicial separation', 'A petition for judicial separation may be presented to the district court by either the husband or the wife on any of the grounds specified in sub-section (1) of section 27.', 'CH5_RESTITUTION_AND_SEPARATION', 'Restitution of Conjugal Rights and Judicial Separation', 12, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-24', 'Void marriages', 'Any marriage solemnized under this Act shall be null and void and may, on a petition presented by either party thereto against the other party, be so declared by a decree of nullity if any of the conditions specified in clauses (a), (b), (c) and (d) of section 4 has not been fulfilled.', 'CH6_NULLITY_AND_DIVORCE', 'Nullity of Marriage and Divorce', 13, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-25', 'Voidable marriages', 'Any marriage solemnized under this Act shall be voidable and may be annulled by a decree of nullity if:\n(i) the marriage has not been consummated owing to the wilful refusal of the respondent;\n(ii) respondent was pregnant by person other than petitioner;\n(iii) consent was obtained by coercion or fraud.', 'CH6_NULLITY_AND_DIVORCE', 'Nullity of Marriage and Divorce', 14, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-27', 'Divorce — Grounds', 'Either husband or wife can petition for divorce on grounds of:\n(a) Voluntary sexual intercourse with others (Adultery).\n(b) Cruelty.\n(c) Desertion for 2 years.\n(d) Imprisonment for 7 years or more.\n(e) Unsound mind or mental disorder.\n(f) Venereal disease in communicable form.\n(g) Leprosy (virulent and incurable).\n(h) Not been heard of as being alive for 7 years.', 'CH6_NULLITY_AND_DIVORCE', 'Nullity of Marriage and Divorce', 15, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-28', 'Divorce by mutual consent', 'Both parties together can petition the district court for divorce on the ground that they have been living separately for a period of one year or more, and have not been able to live together, and have mutually agreed to dissolve marriage.', 'CH6_NULLITY_AND_DIVORCE', 'Nullity of Marriage and Divorce', 16, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-31', 'Court to which petition should be made', 'Every petition shall be presented to the district court within the local limits of whose jurisdiction:\n(i) the marriage was solemnized; or\n(ii) the respondent, at the time of the presentation of the petition, resides; or\n(iii) the parties to the marriage last resided together.', 'CH7_JURISDICTION_AND_PROCEDURE', 'Jurisdiction and Procedure', 17, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-36', 'Alimony pendente lite', 'The court may order the husband to pay to the wife the expenses of the proceeding and maintenance during the pendency of the proceeding if she has no independent income.', 'CH7_JURISDICTION_AND_PROCEDURE', 'Jurisdiction and Procedure', 18, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-37', 'Permanent alimony and maintenance', 'The court may order permanent maintenance to the wife at the time of passing any decree or subsequently.', 'CH7_JURISDICTION_AND_PROCEDURE', 'Jurisdiction and Procedure', 19, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d'),
('SMA-38', 'Custody of children', 'In any proceeding under this Act, the court may from time to time pass interim orders and make such provisions in the decree as it may deem just and proper with respect to the custody, maintenance, and education of minor children.', 'CH7_JURISDICTION_AND_PROCEDURE', 'Jurisdiction and Procedure', 20, '9d33a921-2e11-477d-944a-9e1e4a1f6d4d');
